import numpy as np
def nb(p):
    r,c=divmod(p,9); out=[]
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        rr,cc=r+dr,c+dc
        if 0<=rr<9 and 0<=cc<9: out.append(rr*9+cc)
    return out
def nbd(p):
    r,c=divmod(p,9); d={}
    for k,(dr,dc) in zip('udlr',((-1,0),(1,0),(0,-1),(0,1))):
        rr,cc=r+dr,c+dc
        if 0<=rr<9 and 0<=cc<9: d[k]=rr*9+cc
    return d
def mdist(p,q):
    a,b=divmod(p,9); c,d=divmod(q,9); return abs(a-c)+abs(b-d)
class Layer:
    def __init__(s,nin,nout=512):
        s.nin=nin; s.nout=nout; s.units=[]; s.idx={}
    def add(s,name,terms,bias=0.0):
        assert name not in s.idx
        s.idx[name]=len(s.units); s.units.append((dict(terms),float(bias)))
        assert len(s.units)<=s.nout, ("overflow",name)
        return s.idx[name]
    def __getitem__(s,k): return s.idx[k]
    def mats(s):
        W=np.zeros((s.nin,s.nout),np.float32); b=np.zeros(s.nout,np.float32)
        for j,(t,bb) in enumerate(s.units):
            for i,w in t.items(): W[i,j]+=w
            b[j]=bb
        return W,b
def addt(d,k,w):
    d[k]=d.get(k,0.0)+w
'''
