from lib import *
import net
from net2 import infl_terms, carry, cstep, line
P=range(81)
LINEV=[-2.0,-0.5,0.6,1.0,1.4]
def con_patterns():
    # (e, a, b, c): e empty corner of 2x2 block, a,b its two block-neighbours (own), c diagonal (opp)
    out=[]
    for r in range(8):
        for c in range(8):
            blk=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            for i,(er,ec) in enumerate(blk):
                dr=r+(1 if er==r else 0); dc=c+(1 if ec==c else 0)
                diag=(r if er==r+1 else r+1, c if ec==c+1 else c+1)
                a=(diag[0],ec); b=(er,diag[1])
                out.append((r, er*9+ec, a[0]*9+a[1], b[0]*9+b[1], diag[0]*9+diag[1]))
    return out
def build(inp,prm):
    S=prm['S']; OFF=prm['OFF']
    L1,L2,L3=net.build(inp,prm)[:3]
    pats=con_patterns()
    cut=prm.get('conrow',3)
    for k,(r,e,a,b,c) in enumerate(pats):
        if r<cut: L3.add(('Con',k),{L2['O',a]:1,L2['O',b]:1,L2['X',c]:1},-2)
    for p in P: L3.add(('RI',p),infl_terms(L2,p),0)
    L4=Layer(512); carry(L4,L3); cstep(L4,L3)
    for p in P:
        t={L3['RI',p]:-S*(prm['a']+prm['b'])}
        for k,(r,e,a,b,c) in enumerate(pats):
            if r<cut and e==p: addt(t,L3['Con',k],prm['Wcon'])
        L4.add(('Acc',p),t,OFF)
        deg=len(nb(p)); t={L3['X',p]:8}
        for n in nb(p): addt(t,L3['O',n],1); addt(t,L3['X',n],-7)
        L4.add(('A2s',p),t,3-deg-8)
    L5=Layer(512); carry(L5,L4); cstep(L5,L4)
    for p in P:
        t={L4['Acc',p]:1}
        for n in nb(p): addt(t,L4['A2s',n],prm['Wat'])
        L5.add(('Acc',p),t,0)
        deg=len(nb(p)); t={L4['O',p]:-8,L4['X',p]:-8}
        for n in nb(p): addt(t,L4['O',n],1); addt(t,L4['X',n],-8)
        L5.add(('NE',p),t,-(deg-2))
    L6=Layer(512); cstep(L6,L5)
    for p in P:
        r,c=divmod(p,9); deg=len(nb(p))
        prior=LINEV[line(r)]+LINEV[line(c)]
        t={k:S*prm['b']*v for k,v in infl_terms(L5,p).items()}
        for n in nb(p): addt(t,L5['O',n],-S*prm['cen']); addt(t,L5['X',n],-S*prm['cen'])
        addt(t,L5['Acc',p],1); addt(t,L5['NE',p],-prm['Wne'])
        L6.add(('Acc',p),t,S*(prior+prm['cen']*deg))
        t={L5['O',p]:-8,L5['X',p]:-8}
        for n in nb(p):
            addt(t,L5['O',n],-1); addt(t,L5['X',n],1)
            addt(t,L5['C','own',n],2); addt(t,L5['C','opp',n],-2)
        L6.add(('SA',p),t,2-deg)
    for k,(r,e,a,b,c) in enumerate(pats):
        if r>=cut: L6.add(('Con',k),{L5['O',a]:1,L5['O',b]:1,L5['X',c]:1},-2)
    Wo=np.zeros((512,82),np.float32); bo=np.zeros(82,np.float32)
    for k,(r,e,a,b,c) in enumerate(pats):
        if r>=cut: Wo[L6['Con',k],e]+=prm['Wcon']
    for p in P:
        Wo[L6['Acc',p],p]+=1; bo[p]-=OFF
        Wo[L6['SA',p],p]+=-prm['Wsa']
        for q in P:
            d=mdist(p,q)
            if d==1:
                Wo[L6['C','opp',q],p]+=prm['Wcap']; Wo[L6['C','own',q],p]+=prm['Wsave']
            elif d==2:
                Wo[L6['C','opp',q],p]+=prm['Wcs']; Wo[L6['C','own',q],p]+=prm['Wss']
    bo[81]=prm['PASSV']
    return [L1,L2,L3,L4,L5,L6],Wo,bo
PRM=dict(S=1.5,OFF=80.0,a=1.0,b=0.6,cen=0.2,Wne=15.0,Wsa=6.5,Wcap=10.0,Wsave=5.0,
